package com.example.services;
import java.util.List; import org.springframework.stereotype.Service; import com.example.dtos.*; import com.example.entities.Material; import com.example.repositories.MaterialRepository;
@Service public class MaterialService {private final MaterialRepository repo;public MaterialService(MaterialRepository repo){this.repo=repo;}public List<MaterialResponseDTO> listarTodos(){return repo.findAll().stream().map(this::dto).toList();}public MaterialResponseDTO buscar(Long id){return dto(repo.findById(id).orElseThrow(()->new RuntimeException("Material não encontrado")));}public MaterialResponseDTO salvar(MaterialRequestDTO d){if(d==null||d.getNome()==null||d.getNome().isBlank())throw new RuntimeException("Nome do material é obrigatório");Material m=new Material();m.setNome(d.getNome().trim());return dto(repo.save(m));}public MaterialResponseDTO atualizar(Long id,MaterialRequestDTO d){Material m=repo.findById(id).orElseThrow(()->new RuntimeException("Material não encontrado"));m.setNome(d.getNome().trim());return dto(repo.save(m));}public void deletar(Long id){repo.delete(repo.findById(id).orElseThrow(()->new RuntimeException("Material não encontrado")));}private MaterialResponseDTO dto(Material m){MaterialResponseDTO d=new MaterialResponseDTO();d.setIdMaterial(m.getIdMaterial());d.setNome(m.getNome());return d;}}
